    geoms={g.get('id'):g for g in r.iter(C+'geometry')}
    out=[]
    def mat(n):
        M=np.eye(4)
        for ch in n:
            tag=ch.tag[len(C):]
            if tag=='matrix': M=M@np.array(list(map(float,ch.text.split()))).reshape(4,4)
            elif tag=='translate':
                T=np.eye(4);T[:3,3]=list(map(float,ch.text.split()));M=M@T
            elif tag=='scale':
